{
  "checks": [
    {
      "problem": "链路明细里每个产品只展示开头几步的截图，后面的步骤没有图，读者无法在页面上核对问题清单和结论提到的那些界面。",
      "A": "解决",
      "B": "没解决"
    },
    {
      "problem": "问题清单、改进建议和链路明细之间没有互相引用的定位信息（问题编号、步骤号、屏名），读者要在几节之间来回数步骤、对编号才能把问题、建议和对应界面一一对上。",
      "A": "解决",
      "B": "部分解决"
    }
  ],
  "worse": [
    {
      "version": "B",
      "where": "交互链路（各产品的截图区）",
      "why": "每款产品只排一行、页面上仅露出前 4 步（行下方为横向滚动条），读者要核对云途第 5–6 步、行旅第 5 步、飞鱼第 5–6 步时既无图可看，也无法在一屏内读完一款产品的流程，需横向滚动且滚动后前后步骤不在视野里；A 用网格把 9/7/6/5 步全部摊开，同一步骤的图、步骤号、屏名、问题编号在一张卡上就能读全。"
    },
    {
      "version": "B",
      "where": "交互链路（卡片标题）",
      "why": "A 的每张截图卡标题带问题编号（第3步·选择舱位·P5、第4步·增值服务·P1、第5步·接送机·P4、第6步·填写乘机人·P6），扫一遍截图区就知道哪几步有问题；B 的卡片只写「第X步·屏名」，读者必须记着问题明细里的产品+步骤号再回截图区数步骤。"
    }
  ],
  "better": "A",
  "reason": "A 把四款 App 的完整链路截图（云途 9 步、行旅 7 步、飞鱼 6 步、北极星 5 步）全部摊开，并在截图卡标题上直接标出问题编号，读者拿一条问题或建议就能一步找到对应界面；B 每款只放下前 4 步且没有编号回链，多数问题在页面上无图可核。",
  "next": [
    {
      "where": "链路明细 · 按产品分块的截图区",
      "task": "对照同一环节在不同产品上的表现，例如「附加产品」看云途第 4–5 步、行旅第 5 步、飞鱼第 5 步",
      "why": "截图块按产品纵向排列，同一环节分散在三块里，各家的步骤号还不一致（云途第 4 步、行旅第 5 步、飞鱼第 5 步），读者要上下滚动并自己换算步骤号，无法并排对照同一环节的几张图。"
    },
    {
      "where": "关键环节表",
      "task": "看完某个环节的结论后跳到对应界面去核对",
      "why": "表里只有文字结论，没有步骤号、问题编号或缩略图指针，读者要自己翻到链路里对应产品的块中数步骤；链路卡上的问题编号只能反向（截图→问题）用，表格到截图仍是正向换算。"
    }
  ]
}
